using System;
using System.Collections.Generic;
using Framework.AI.Core;
using Framework.Movement;
using Framework.Parameters;
using Game.AI.Core;
using Game.AI.Parameters;
using Game.AI.Spatial;
using Game.Map;
using Game.Stage;
using UnityEngine;

namespace Game.Tests
{
    /// <summary>
    /// 敵AIの空間評価システムを検証する。
    /// </summary>
    [DisallowMultipleComponent]
    public sealed class MazeEnemySpatialEvaluatorTest : MonoBehaviour
    {
        [Header("テスト設定")]

        [SerializeField]
        [Tooltip("テスト用ステージ管理Prefab。")]
        private MazeStageManager stageManagerPrefab;

        [SerializeField]
        [Tooltip("開始時にテストを実行する。")]
        private bool runTestsOnStart = true;

        [Header("テスト結果")]

        [SerializeField]
        [Tooltip("成功したテスト件数。")]
        private int passedCount;

        [SerializeField]
        [Tooltip("失敗したテスト件数。")]
        private int failedCount;

        /// <summary>
        /// 予定されているテスト件数。
        /// </summary>
        private const int ExpectedTestCount = 48;

        /// <summary>
        /// 浮動小数点数の比較許容誤差。
        /// </summary>
        private const float Tolerance = 0.0001f;

        /// <summary>
        /// テスト用の初期座標。
        /// </summary>
        private static readonly Vector2Int Origin =
            new Vector2Int(1, 1);

        /// <summary>
        /// テスト用のステージ管理インスタンス。
        /// </summary>
        private MazeStageManager stageManager;

        /// <summary>
        /// テスト用の移動オブジェクト。
        /// </summary>
        private GameObject movementObject;

        /// <summary>
        /// テスト用の移動コントローラー。
        /// </summary>
        private GridMovementController movement;

        /// <summary>
        /// テスト用のパラメーターセット。
        /// </summary>
        private ParameterSet<MazeEnemyParameter> parameters;

        /// <summary>
        /// テスト用の敵AIコンテキスト。
        /// </summary>
        private MazeEnemyContext context;

        /// <summary>
        /// テスト用の縄張り評価システム。
        /// </summary>
        private MazeEnemyTerritory territory;

        /// <summary>
        /// テスト対象の空間評価システム。
        /// </summary>
        private MazeEnemySpatialEvaluator evaluator;

        /// <summary>
        /// 開始時にテストを実行する。
        /// </summary>
        private void Start()
        {
            if (runTestsOnStart)
            {
                RunAllTests();
            }
        }

        /// <summary>
        /// すべてのテストを実行する。
        /// </summary>
        [ContextMenu("すべてのテストを実行")]
        public void RunAllTests()
        {
            if (!Application.isPlaying)
            {
                Debug.LogWarning(
                    "Play Modeで実行してください。",
                    this);

                return;
            }

            passedCount = 0;
            failedCount = 0;

            try
            {
                Prepare();
                TestInitialization();

                Prepare();
                TestEvaluation();

                Prepare();
                TestParametersAndMemory();

                Prepare();
                TestSelection();

                Prepare();
                TestCache();

                Prepare();
                TestLifecycle();
            }
            catch (Exception exception)
            {
                failedCount++;

                Debug.LogException(exception, this);
            }
            finally
            {
                Cleanup();
            }

            Debug.Log(
                $"【MazeEnemySpatialEvaluator テスト結果】\n" +
                $"成功：{passedCount}\n" +
                $"失敗：{failedCount}\n" +
                (passedCount == ExpectedTestCount &&
                 failedCount == 0
                    ? "すべてのテストに成功しました。"
                    : "失敗または未実行のテストがあります。"),
                this);
        }

        /// <summary>
        /// テスト環境を初期化する。
        /// </summary>
        private void Prepare()
        {
            Cleanup();

            if (stageManagerPrefab == null)
            {
                throw new InvalidOperationException(
                    "テスト用ステージPrefabが未設定です。");
            }

            stageManager = Instantiate(stageManagerPrefab);

            if (!stageManager.GenerateStage())
            {
                throw new InvalidOperationException(
                    "テスト用ステージの生成に失敗しました。");
            }

            if (stageManager.Map.Width < 10 ||
                stageManager.Map.Height < 5)
            {
                throw new InvalidOperationException(
                    "テスト用グリッドは10×5以上が必要です。");
            }

            // 固定された通行条件でテストする。
            stageManager.Map.Fill(MazeCell.CreateFloor());

            movementObject =
                new GameObject("SpatialTest_Movement");

            movement = movementObject
                .AddComponent<GridMovementController>();

            movement.AutoUpdate = false;

            movement.Initialize(
                stageManager.CoordinateConverter,
                stageManager.IsWalkable,
                Origin);

            movement.MoveSpeed = 1f;

            parameters =
                MazeEnemyParameterCatalog.CreateParameterSet();

            parameters.SetBaseValue(
                MazeEnemyParameter.TerritoryRadius,
                4f);

            parameters.SetBaseValue(
                MazeEnemyParameter.Territoriality,
                0.8f);

            parameters.SetBaseValue(
                MazeEnemyParameter.Exploration,
                0.8f);

            parameters.SetBaseValue(
                MazeEnemyParameter.PatrolPreference,
                0.7f);

            parameters.SetBaseValue(
                MazeEnemyParameter.VisitMemoryDuration,
                30f);

            var agentContext =
                new AgentContext<MazeEnemyParameter>(
                    "SpatialTest",
                    parameters);

            context = new MazeEnemyContext(
                agentContext,
                stageManager,
                movement,
                Origin);

            territory = new MazeEnemyTerritory(context);

            evaluator = new MazeEnemySpatialEvaluator(
                context,
                territory);
        }

        /// <summary>
        /// 初期状態と引数検証を確認する。
        /// </summary>
        private void TestInitialization()
        {
            bool contextPassed =
                ReferenceEquals(
                    evaluator.Context,
                    context);

            Debug.Assert(contextPassed, "コンテキスト参照", this);
            Check(contextPassed, "コンテキスト参照");

            bool territoryPassed =
                ReferenceEquals(
                    evaluator.Territory,
                    territory);

            Debug.Assert(territoryPassed, "縄張り評価参照", this);
            Check(territoryPassed, "縄張り評価参照");

            bool validPassed =
                evaluator.IsValid &&
                !evaluator.IsDisposed;

            Debug.Assert(validPassed, "初期有効状態", this);
            Check(validPassed, "初期有効状態");

            bool originPassed =
                evaluator.Origin == Origin;

            Debug.Assert(originPassed, "初期探索起点", this);
            Check(originPassed, "初期探索起点");

            bool lazyPassed =
                evaluator.IsDirty &&
                evaluator.RecalculationCount == 0 &&
                evaluator.LastCandidateCount == 0;

            Debug.Assert(lazyPassed, "初期遅延計算状態", this);
            Check(lazyPassed, "初期遅延計算状態");

            bool nullContextPassed =
                Throws<ArgumentNullException>(() =>
                {
                    new MazeEnemySpatialEvaluator(
                        null,
                        territory);
                });

            Debug.Assert(nullContextPassed, "nullコンテキストの拒否", this);
            Check(nullContextPassed, "nullコンテキストの拒否");

            bool nullTerritoryPassed =
                Throws<ArgumentNullException>(() =>
                {
                    new MazeEnemySpatialEvaluator(
                        context,
                        null);
                });

            Debug.Assert(nullTerritoryPassed, "null縄張り評価の拒否", this);
            Check(nullTerritoryPassed, "null縄張り評価の拒否");

            territory.Dispose();

            bool invalidPassed =
                Throws<ArgumentException>(() =>
                {
                    new MazeEnemySpatialEvaluator(
                        context,
                        territory);
                });

            Debug.Assert(invalidPassed, "無効な縄張り評価の拒否", this);
            Check(invalidPassed, "無効な縄張り評価の拒否");
        }

        /// <summary>
        /// 移動距離と空間評価の計算を確認する。
        /// </summary>
        private void TestEvaluation()
        {
            Vector2Int target =
                new Vector2Int(3, 1);

            bool distancePassed =
                evaluator.GetDistance(target) == 2;

            Debug.Assert(distancePassed, "最短移動距離", this);
            Check(distancePassed, "最短移動距離");

            bool evaluationPassed =
                evaluator.TryEvaluate(
                    target,
                    MazeEnemySpatialMode.Exploration,
                    out var exploration) &&
                exploration.IsValid &&
                exploration.Position == target &&
                exploration.Origin == Origin &&
                exploration.Distance == 2;

            Debug.Assert(evaluationPassed, "空間評価結果の生成", this);
            Check(evaluationPassed, "空間評価結果の生成");

            bool distanceScorePassed =
                Approximately(
                    exploration.DistanceScore,
                    1f / 1.4f);

            Debug.Assert(distanceScorePassed, "距離評価値", this);
            Check(distanceScorePassed, "距離評価値");

            bool explorationPassed =
                Approximately(
                    exploration.UnvisitedScore,
                    1f) &&
                Approximately(
                    exploration.Score,
                    0.5f + 0.5f / 1.4f);

            Debug.Assert(explorationPassed, "探索地点の評価計算", this);
            Check(explorationPassed, "探索地点の評価計算");

            bool patrolPassed =
                evaluator.TryEvaluate(
                    target,
                    MazeEnemySpatialMode.Patrol,
                    out var patrol) &&
                Approximately(
                    patrol.Score,
                    0.3f + 0.7f / 1.4f);

            Debug.Assert(patrolPassed, "巡回地点の評価計算", this);
            Check(patrolPassed, "巡回地点の評価計算");

            bool originPassed =
                !evaluator.TryEvaluate(
                    Origin,
                    MazeEnemySpatialMode.Exploration,
                    out var originEvaluation) &&
                !originEvaluation.IsValid;

            Debug.Assert(originPassed, "起点自身の評価除外", this);
            Check(originPassed, "起点自身の評価除外");

            bool outsidePassed =
                !evaluator.TryEvaluate(
                    new Vector2Int(-1, 0),
                    MazeEnemySpatialMode.Patrol,
                    out var outsideEvaluation) &&
                !outsideEvaluation.IsValid;

            Debug.Assert(outsidePassed, "グリッド外の評価拒否", this);
            Check(outsidePassed, "グリッド外の評価拒否");

            stageManager.Map.SetCell(
                new Vector2Int(2, 1),
                MazeCell.CreateWall());

            bool wallPassed =
                evaluator.GetDistance(target) == 4 &&
                !evaluator.TryEvaluate(
                    new Vector2Int(2, 1),
                    MazeEnemySpatialMode.Exploration,
                    out _);

            Debug.Assert(wallPassed, "壁の迂回と評価除外", this);
            Check(wallPassed, "壁の迂回と評価除外");
        }

        /// <summary>
        /// 性格パラメーターと訪問記憶の反映を確認する。
        /// </summary>
        private void TestParametersAndMemory()
        {
            Vector2Int target =
                new Vector2Int(3, 1);

            evaluator.TryEvaluate(
                target,
                MazeEnemySpatialMode.Exploration,
                out var unvisited);

            // 訪問履歴を記録する。
            bool recorded =
                context.RecordVisit(target);

            evaluator.TryEvaluate(
                target,
                MazeEnemySpatialMode.Exploration,
                out var visited);

            bool memoryPassed =
                recorded &&
                Approximately(
                    unvisited.UnvisitedScore,
                    1f) &&
                Approximately(
                    visited.UnvisitedScore,
                    0f) &&
                visited.Score < unvisited.Score;

            Debug.Assert(memoryPassed, "訪問記憶による評価低下", this);
            Check(memoryPassed, "訪問記憶による評価低下");

            parameters.SetBaseValue(
                MazeEnemyParameter.Exploration,
                0f);

            evaluator.TryEvaluate(
                target,
                MazeEnemySpatialMode.Exploration,
                out var lowExploration);

            bool lowPassed =
                Approximately(
                    lowExploration.Score,
                    unvisited.Score);

            Debug.Assert(lowPassed, "探索傾向0の評価", this);
            Check(lowPassed, "探索傾向0の評価");

            parameters.SetBaseValue(
                MazeEnemyParameter.Exploration,
                1f);

            evaluator.TryEvaluate(
                target,
                MazeEnemySpatialMode.Exploration,
                out var highExploration);

            bool highPassed =
                highExploration.IsValid &&
                Approximately(
                    highExploration.Score,
                    0f);

            Debug.Assert(highPassed, "探索傾向最大の評価", this);
            Check(highPassed, "探索傾向最大の評価");

            parameters.SetBaseValue(
                MazeEnemyParameter.PatrolPreference,
                0f);

            evaluator.TryEvaluate(
                target,
                MazeEnemySpatialMode.Patrol,
                out var lowPatrol);

            bool lowPatrolPassed =
                Approximately(
                    lowPatrol.Score,
                    0.25f);

            Debug.Assert(lowPatrolPassed, "巡回傾向0の評価", this);
            Check(lowPatrolPassed, "巡回傾向0の評価");

            parameters.SetBaseValue(
                MazeEnemyParameter.PatrolPreference,
                1f);

            evaluator.TryEvaluate(
                target,
                MazeEnemySpatialMode.Patrol,
                out var highPatrol);

            bool highPatrolPassed =
                Approximately(
                    highPatrol.Score,
                    0.25f / 1.4f);

            Debug.Assert(highPatrolPassed, "巡回傾向最大の評価", this);
            Check(highPatrolPassed, "巡回傾向最大の評価");

            parameters.SetBaseValue(
                MazeEnemyParameter.VisitMemoryDuration,
                0f);

            evaluator.TryEvaluate(
                target,
                MazeEnemySpatialMode.Exploration,
                out var memoryDisabled);

            bool disabledPassed =
                Approximately(
                    memoryDisabled.UnvisitedScore,
                    1f);

            Debug.Assert(disabledPassed, "訪問記憶無効時の評価", this);
            Check(disabledPassed, "訪問記憶無効時の評価");

            Vector2Int outside =
                new Vector2Int(7, 1);

            evaluator.TryEvaluate(
                outside,
                MazeEnemySpatialMode.Exploration,
                out var territorial);

            bool territoryPassed =
                territorial.TerritoryEvaluation.IsValid &&
                Approximately(
                    territorial.TerritoryMultiplier,
                    0.64f) &&
                Approximately(
                    territorial.Score,
                    (0.5f + 0.5f / 2.2f) * 0.64f);

            Debug.Assert(territoryPassed, "縄張り評価倍率の反映", this);
            Check(territoryPassed, "縄張り評価倍率の反映");

            parameters.SetBaseValue(
                MazeEnemyParameter.Territoriality,
                0f);

            evaluator.TryEvaluate(
                outside,
                MazeEnemySpatialMode.Exploration,
                out var unrestricted);

            bool unrestrictedPassed =
                Approximately(
                    unrestricted.TerritoryMultiplier,
                    1f) &&
                unrestricted.Score > territorial.Score &&
                evaluator.RecalculationCount == 1;

            Debug.Assert(unrestrictedPassed, "性格変更時の再評価とキャッシュ維持", this);
            Check(unrestrictedPassed, "性格変更時の再評価とキャッシュ維持");
        }

        /// <summary>
        /// 移動先候補の選定を確認する。
        /// </summary>
        private void TestSelection()
        {
            bool selectPassed =
                evaluator.TrySelectBestPosition(
                    MazeEnemySpatialMode.Exploration,
                    out var best) &&
                best.IsValid &&
                best.Position != Origin;

            Debug.Assert(selectPassed, "探索地点の選定", this);
            Check(selectPassed, "探索地点の選定");

            // 全候補が未訪問の場合は近い地点が優先される。
            bool tiePassed =
                best.Position == new Vector2Int(1, 0) &&
                best.Distance == 1;

            Debug.Assert(tiePassed, "同点時の安定した選定", this);
            Check(tiePassed, "同点時の安定した選定");

            bool rangePassed =
                evaluator.TrySelectBestPosition(
                    MazeEnemySpatialMode.Patrol,
                    out var patrol,
                    3,
                    5) &&
                patrol.Distance >= 3 &&
                patrol.Distance <= 5;

            Debug.Assert(rangePassed, "移動距離範囲の指定", this);
            Check(rangePassed, "移動距離範囲の指定");

            // 最初に選ばれた地点を訪問済みにする。
            context.RecordVisit(best.Position);

            bool noveltyPassed =
                evaluator.TrySelectBestPosition(
                    MazeEnemySpatialMode.Exploration,
                    out var next,
                    1,
                    1) &&
                next.Position != best.Position &&
                Approximately(
                    next.UnvisitedScore,
                    1f);

            Debug.Assert(noveltyPassed, "未訪問地点の優先選定", this);
            Check(noveltyPassed, "未訪問地点の優先選定");

            var results =
                new List<MazeEnemySpatialEvaluation>();

            int count = evaluator.GetEvaluations(
                MazeEnemySpatialMode.Patrol,
                results,
                1,
                1);

            bool listPassed =
                count == 4 &&
                results.Count == 4 &&
                evaluator.LastCandidateCount == 4;

            Debug.Assert(listPassed, "候補評価一覧の取得", this);
            Check(listPassed, "候補評価一覧の取得");

            int secondCount = evaluator.GetEvaluations(
                MazeEnemySpatialMode.Exploration,
                results,
                2,
                2);

            // 起点が(1,1)のため、距離2のセルは6個。
            bool reusePassed =
                secondCount == 6 &&
                results.Count == 6;

            Debug.Assert(reusePassed, "評価一覧の再利用", this);
            Check(reusePassed, "評価一覧の再利用");

            bool invalidRangePassed =
                !evaluator.TrySelectBestPosition(
                    MazeEnemySpatialMode.Patrol,
                    out _,
                    0,
                    5) &&
                !evaluator.TrySelectBestPosition(
                    MazeEnemySpatialMode.Patrol,
                    out _,
                    5,
                    2) &&
                evaluator.LastCandidateCount == 0;

            Debug.Assert(invalidRangePassed, "無効な距離範囲の拒否", this);
            Check(invalidRangePassed, "無効な距離範囲の拒否");

            // 起点以外をすべて壁にする。
            stageManager.Map.Fill(MazeCell.CreateWall());

            stageManager.Map.SetCell(
                Origin,
                MazeCell.CreateFloor());

            bool emptyPassed =
                !evaluator.TrySelectBestPosition(
                    MazeEnemySpatialMode.Exploration,
                    out var emptyEvaluation) &&
                !emptyEvaluation.IsValid &&
                evaluator.LastCandidateCount == 0;

            Debug.Assert(emptyPassed, "候補が存在しない場合の処理", this);
            Check(emptyPassed, "候補が存在しない場合の処理");
        }

        /// <summary>
        /// 距離キャッシュと移動制御の連携を確認する。
        /// </summary>
        private void TestCache()
        {
            bool firstPassed =
                evaluator.Refresh() &&
                evaluator.RecalculationCount == 1 &&
                !evaluator.IsDirty;

            Debug.Assert(firstPassed, "初回距離計算", this);
            Check(firstPassed, "初回距離計算");

            evaluator.TrySelectBestPosition(
                MazeEnemySpatialMode.Exploration,
                out _);

            evaluator.TrySelectBestPosition(
                MazeEnemySpatialMode.Patrol,
                out _);

            bool reusePassed =
                evaluator.RecalculationCount == 1;

            Debug.Assert(reusePassed, "評価方式間のキャッシュ共有", this);
            Check(reusePassed, "評価方式間のキャッシュ共有");

            stageManager.Map.SetCell(
                new Vector2Int(2, 2),
                MazeCell.CreateFloor(MazeCellFlags.Gem));

            bool gemPassed =
                !evaluator.IsDirty &&
                evaluator.Refresh() &&
                evaluator.RecalculationCount == 1;

            Debug.Assert(gemPassed, "宝石変更時の再計算抑制", this);
            Check(gemPassed, "宝石変更時の再計算抑制");

            stageManager.Map.SetCell(
                new Vector2Int(2, 2),
                MazeCell.CreateWall());

            stageManager.Map.SetCell(
                new Vector2Int(3, 2),
                MazeCell.CreateWall());

            bool dirtyPassed =
                evaluator.IsDirty &&
                evaluator.RecalculationCount == 1;

            Debug.Assert(dirtyPassed, "通行条件変更時の遅延更新", this);
            Check(dirtyPassed, "通行条件変更時の遅延更新");

            bool batchPassed =
                evaluator.Refresh() &&
                evaluator.RecalculationCount == 2 &&
                !evaluator.IsDirty;

            Debug.Assert(batchPassed, "複数変更の一括再計算", this);
            Check(batchPassed, "複数変更の一括再計算");

            movement.RequestDirection(
                Vector2Int.right);

            movement.Tick(0.5f);

            bool movingPassed =
                movement.IsTraversing &&
                evaluator.Origin == new Vector2Int(2, 1) &&
                evaluator.IsDirty &&
                evaluator.Refresh() &&
                evaluator.RecalculationCount == 3;

            Debug.Assert(movingPassed, "移動途中の探索起点変更", this);
            Check(movingPassed, "移動途中の探索起点変更");

            movement.RequestStop();

            movement.Tick(0.5f);

            bool arrivedPassed =
                movement.CurrentCell ==
                    new Vector2Int(2, 1) &&
                evaluator.Origin ==
                    new Vector2Int(2, 1) &&
                evaluator.Refresh() &&
                evaluator.RecalculationCount == 3;

            Debug.Assert(arrivedPassed, "到達時のキャッシュ維持", this);
            Check(arrivedPassed, "到達時のキャッシュ維持");

            bool teleported =
                movement.TryTeleport(
                    new Vector2Int(4, 1));

            bool teleportPassed =
                teleported &&
                evaluator.IsDirty &&
                evaluator.GetDistance(
                    new Vector2Int(5, 1)) == 1 &&
                evaluator.RecalculationCount == 4;

            Debug.Assert(teleportPassed, "瞬間移動後の距離更新", this);
            Check(teleportPassed, "瞬間移動後の距離更新");
        }

        /// <summary>
        /// ライフサイクルと無効状態への対応を確認する。
        /// </summary>
        private void TestLifecycle()
        {
            bool modePassed =
                !evaluator.TryEvaluate(
                    new Vector2Int(2, 1),
                    (MazeEnemySpatialMode)999,
                    out var invalidEvaluation) &&
                !invalidEvaluation.IsValid;

            Debug.Assert(modePassed, "無効な評価方式の拒否", this);
            Check(modePassed, "無効な評価方式の拒否");

            bool nullListPassed =
                Throws<ArgumentNullException>(() =>
                {
                    evaluator.GetEvaluations(
                        MazeEnemySpatialMode.Patrol,
                        null);
                });

            Debug.Assert(nullListPassed, "null格納先の拒否", this);
            Check(nullListPassed, "null格納先の拒否");

            evaluator.Refresh();

            long initialCount =
                evaluator.RecalculationCount;

            evaluator.Invalidate();

            bool invalidatePassed =
                evaluator.IsDirty &&
                evaluator.Refresh() &&
                evaluator.RecalculationCount ==
                    initialCount + 1;

            Debug.Assert(invalidatePassed, "明示的なキャッシュ無効化", this);
            Check(invalidatePassed, "明示的なキャッシュ無効化");

            // 縄張り中心から離れた後、中心を壁にする。
            movement.TryTeleport(
                new Vector2Int(3, 1));

            stageManager.Map.SetCell(
                Origin,
                MazeCell.CreateWall());

            bool fallbackPassed =
                evaluator.TryEvaluate(
                    new Vector2Int(4, 1),
                    MazeEnemySpatialMode.Exploration,
                    out var fallback) &&
                !fallback.TerritoryEvaluation.IsValid &&
                Approximately(
                    fallback.TerritoryMultiplier,
                    1f);

            Debug.Assert(fallbackPassed, "無効な縄張りからの評価継続", this);
            Check(fallbackPassed, "無効な縄張りからの評価継続");

            // 自身の探索起点も通行不可能にする。
            stageManager.Map.SetCell(
                movement.CurrentCell,
                MazeCell.CreateWall());

            bool blockedPassed =
                !evaluator.Refresh() &&
                !evaluator.TrySelectBestPosition(
                    MazeEnemySpatialMode.Patrol,
                    out _);

            Debug.Assert(blockedPassed, "無効な探索起点への対応", this);
            Check(blockedPassed, "無効な探索起点への対応");

            stageManager.Map.SetCell(
                movement.CurrentCell,
                MazeCell.CreateFloor());

            bool recoveryPassed =
                evaluator.Refresh() &&
                evaluator.TrySelectBestPosition(
                    MazeEnemySpatialMode.Patrol,
                    out _);

            Debug.Assert(recoveryPassed, "通行条件復旧後の再評価", this);
            Check(recoveryPassed, "通行条件復旧後の再評価");

            evaluator.Dispose();
            evaluator.Dispose();

            bool disposedPassed =
                evaluator.IsDisposed &&
                !evaluator.IsValid &&
                !evaluator.IsDirty &&
                !evaluator.Refresh() &&
                evaluator.GetDistance(Origin) == -1 &&
                context.IsValid &&
                territory.IsValid &&
                !parameters.IsDisposed;

            Debug.Assert(disposedPassed, "重複破棄と外部所有権の維持", this);
            Check(disposedPassed, "重複破棄と外部所有権の維持");

            evaluator = new MazeEnemySpatialEvaluator(
                context,
                territory);

            territory.Dispose();

            bool dependencyPassed =
                !evaluator.IsValid &&
                !evaluator.TrySelectBestPosition(
                    MazeEnemySpatialMode.Exploration,
                    out _);

            Debug.Assert(dependencyPassed, "依存システム破棄への対応", this);
            Check(dependencyPassed, "依存システム破棄への対応");
        }

        /// <summary>
        /// 浮動小数点数が許容誤差以内で一致するか確認する。
        /// </summary>
        /// <param name="actual">実際の値</param>
        /// <param name="expected">期待する値</param>
        /// <returns>許容誤差以内の場合はtrue</returns>
        private bool Approximately(
            float actual,
            float expected)
        {
            return Mathf.Abs(actual - expected) <=
                Tolerance;
        }

        /// <summary>
        /// 指定された型の例外が発生するか確認する。
        /// </summary>
        /// <typeparam name="TException">期待する例外型</typeparam>
        /// <param name="action">実行する処理</param>
        /// <returns>期待する例外が発生した場合はtrue</returns>
        private bool Throws<TException>(Action action)
            where TException : Exception
        {
            try
            {
                action();

                return false;
            }
            catch (Exception exception)
            {
                return exception.GetType() ==
                    typeof(TException);
            }
        }

        /// <summary>
        /// テスト環境を破棄する。
        /// </summary>
        private void Cleanup()
        {
            // 依存する側から順番に破棄する。
            evaluator?.Dispose();
            evaluator = null;

            territory?.Dispose();
            territory = null;

            context?.Dispose();
            context = null;

            parameters?.Dispose();
            parameters = null;

            if (movementObject != null)
            {
                movementObject.SetActive(false);

                Destroy(movementObject);

                movementObject = null;
            }

            movement = null;

            if (stageManager != null)
            {
                stageManager.gameObject.SetActive(false);

                Destroy(stageManager.gameObject);

                stageManager = null;
            }
        }

        /// <summary>
        /// オブジェクト破棄時にテスト環境を解放する。
        /// </summary>
        private void OnDestroy()
        {
            Cleanup();
        }

        /// <summary>
        /// 個別のテスト結果を出力して集計する。
        /// </summary>
        /// <param name="passed">成功判定</param>
        /// <param name="testName">テスト名</param>
        private void Check(bool passed, string testName)
        {
            if (passed)
            {
                passedCount++;

                Debug.Log(
                    $"<color=#00CC66>【成功】</color> {testName}",
                    this);
            }
            else
            {
                failedCount++;

                Debug.LogError(
                    $"【失敗】{testName}",
                    this);
            }
        }
    }
